/**
 * What a case ciphertext is. The only choice a caller of this module makes —
 * it names the thing being sealed, never how. Every binding carries it as a
 * closed type: a UniFFI enum (Swift/Kotlin), a lowercase string the Tauri IPC
 * deserialises into this enum (`"summary"`/`"fields"`/`"comment"`), and a byte
 * on the server's C ABI.
 *
 * `repr(u8)` because the server's C ABI carries it as a byte; the mapping is
 * closed ([`CasePurpose::from_u8`] rejects anything else).
 */

enum class CasePurpose(val value: kotlin.UByte) {
    
    /**
     * A case record's summary (title, description, status display).
     */
    SUMMARY(0u),
    /**
     * A case record's custom-field values.
     */
    FIELDS(1u),
    /**
     * A comment interaction on a case record's timeline.
     */
    COMMENT(2u);

    


    companion object
}


/**
 * @suppress
 */
public object FfiConverterTypeCasePurpose: FfiConverterRustBuffer<CasePurpose> {
    override fun read(buf: ByteBuffer) = try {
        CasePurpose.values()[buf.getInt() - 1]
    } catch (e: IndexOutOfBoundsException) {
        throw RuntimeException("invalid enum value, something is very wrong!!", e)
    }

    override fun allocationSize(value: CasePurpose) = 4UL

    override fun write(value: CasePurpose, buf: ByteBuffer) {
        buf.putInt(value.ordinal + 1)
    }
}







sealed class CryptoException(message: String): kotlin.Exception(message) {
        
        class InvalidSecretKey(message: String) : CryptoException(message)
        
        class InvalidPublicKey(message: String) : CryptoException(message)
        
        class InvalidEphemeralKey(message: String) : CryptoException(message)
        
        class EcdhFailed(message: String) : CryptoException(message)
        
        class EncryptionFailed(message: String) : CryptoException(message)
        
        class DecryptionFailed(message: String) : CryptoException(message)
        
        class HexException(message: String) : CryptoException(message)
        
        class InvalidNonce(message: String) : CryptoException(message)
        
        class InvalidCiphertext(message: String) : CryptoException(message)
        
        class KeyDerivationFailed(message: String) : CryptoException(message)
        
        class SignatureVerificationFailed(message: String) : CryptoException(message)
        
        class JsonException(message: String) : CryptoException(message)
        
        class WrongPin(message: String) : CryptoException(message)
        
        class InvalidPin(message: String) : CryptoException(message)
        
        class InvalidInput(message: String) : CryptoException(message)
        
        class InvalidFormat(message: String) : CryptoException(message)
        
        class HkdfExpandException(message: String) : CryptoException(message)
        
        class InvalidSignature(message: String) : CryptoException(message)
        
        class StaleTimestamp(message: String) : CryptoException(message)
        
        class FutureTimestamp(message: String) : CryptoException(message)
        
    /**
     * An identifier outside the §2.1 profile (`^[0-9a-z][0-9a-z-]{0,63}$` or lowercase hex).
     */
        class InvalidIdentifier(message: String) : CryptoException(message)
        
    /**
     * No relay-event key is held for this hub and epoch.
     */
        class NoEventKey(message: String) : CryptoException(message)
        
    /**
     * A user sigchain refused by one of its closed rules. `code` is the
     * rejection code the vectors name (`chain_device_pop`, `chain_key_reused`,
     * `chain_unauthorised_signer`, …); see [`crate::sigchain`].
     */
        class SigchainRejected(message: String) : CryptoException(message)
        
    /**
     * The hub has no admin reader to seal to. See [`crate::readers`].
     */
        class NoAdminReader(message: String) : CryptoException(message)
        

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<CryptoException> {
        override fun lift(error_buf: RustBuffer.ByValue): CryptoException = FfiConverterTypeCryptoError.lift(error_buf)
    }
}

/**
 * @suppress
 */
public object FfiConverterTypeCryptoError : FfiConverterRustBuffer<CryptoException> {
    override fun read(buf: ByteBuffer): CryptoException {
        
            return when(buf.getInt()) {
            1 -> CryptoException.InvalidSecretKey(FfiConverterString.read(buf))
            2 -> CryptoException.InvalidPublicKey(FfiConverterString.read(buf))
            3 -> CryptoException.InvalidEphemeralKey(FfiConverterString.read(buf))
            4 -> CryptoException.EcdhFailed(FfiConverterString.read(buf))
            5 -> CryptoException.EncryptionFailed(FfiConverterString.read(buf))
            6 -> CryptoException.DecryptionFailed(FfiConverterString.read(buf))
            7 -> CryptoException.HexException(FfiConverterString.read(buf))
            8 -> CryptoException.InvalidNonce(FfiConverterString.read(buf))
            9 -> CryptoException.InvalidCiphertext(FfiConverterString.read(buf))
            10 -> CryptoException.KeyDerivationFailed(FfiConverterString.read(buf))
            11 -> CryptoException.SignatureVerificationFailed(FfiConverterString.read(buf))
            12 -> CryptoException.JsonException(FfiConverterString.read(buf))
            13 -> CryptoException.WrongPin(FfiConverterString.read(buf))
            14 -> CryptoException.InvalidPin(FfiConverterString.read(buf))
            15 -> CryptoException.InvalidInput(FfiConverterString.read(buf))
            16 -> CryptoException.InvalidFormat(FfiConverterString.read(buf))
            17 -> CryptoException.HkdfExpandException(FfiConverterString.read(buf))
            18 -> CryptoException.InvalidSignature(FfiConverterString.read(buf))
            19 -> CryptoException.StaleTimestamp(FfiConverterString.read(buf))
            20 -> CryptoException.FutureTimestamp(FfiConverterString.read(buf))
            21 -> CryptoException.InvalidIdentifier(FfiConverterString.read(buf))
            22 -> CryptoException.NoEventKey(FfiConverterString.read(buf))
            23 -> CryptoException.SigchainRejected(FfiConverterString.read(buf))
            24 -> CryptoException.NoAdminReader(FfiConverterString.read(buf))
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
        
    }

    override fun allocationSize(value: CryptoException): ULong {
        return 4UL
    }

    override fun write(value: CryptoException, buf: ByteBuffer) {
        when(value) {
            is CryptoException.InvalidSecretKey -> {
                buf.putInt(1)
                Unit
            }
            is CryptoException.InvalidPublicKey -> {
                buf.putInt(2)
                Unit
            }
            is CryptoException.InvalidEphemeralKey -> {
                buf.putInt(3)
                Unit
            }
            is CryptoException.EcdhFailed -> {
                buf.putInt(4)
                Unit
            }
            is CryptoException.EncryptionFailed -> {
                buf.putInt(5)
                Unit
            }
            is CryptoException.DecryptionFailed -> {
                buf.putInt(6)
                Unit
            }
            is CryptoException.HexException -> {
                buf.putInt(7)
                Unit
            }
            is CryptoException.InvalidNonce -> {
                buf.putInt(8)
                Unit
            }
            is CryptoException.InvalidCiphertext -> {
                buf.putInt(9)
                Unit
            }
            is CryptoException.KeyDerivationFailed -> {
                buf.putInt(10)
                Unit
            }
            is CryptoException.SignatureVerificationFailed -> {
                buf.putInt(11)
                Unit
            }
            is CryptoException.JsonException -> {
                buf.putInt(12)
                Unit
            }
            is CryptoException.WrongPin -> {
                buf.putInt(13)
                Unit
            }
            is CryptoException.InvalidPin -> {
                buf.putInt(14)
                Unit
            }
            is CryptoException.InvalidInput -> {
                buf.putInt(15)
                Unit
            }
            is CryptoException.InvalidFormat -> {
                buf.putInt(16)
                Unit
            }
            is CryptoException.HkdfExpandException -> {
                buf.putInt(17)
                Unit
            }
            is CryptoException.InvalidSignature -> {
                buf.putInt(18)
                Unit
            }
            is CryptoException.StaleTimestamp -> {
                buf.putInt(19)
                Unit
            }
            is CryptoException.FutureTimestamp -> {
                buf.putInt(20)
                Unit
            }
            is CryptoException.InvalidIdentifier -> {
                buf.putInt(21)
                Unit
            }
            is CryptoException.NoEventKey -> {
                buf.putInt(22)
                Unit
            }
            is CryptoException.SigchainRejected -> {
                buf.putInt(23)
                Unit
            }
            is CryptoException.NoAdminReader -> {
                buf.putInt(24)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}



/**
 * What an HPKE envelope is. Closed: a host names one of these and nothing else.
 *
 * Carried as a UniFFI enum (Swift/Kotlin), a kebab-case string on the Tauri IPC
 * (`"note-key"`), and a byte on the server's C ABI ([`Shape::from_u8`]).
 */

enum class Shape(val value: kotlin.UByte) {
    
    /**
     * A note's per-note content key.
     */
    NOTE_KEY(0u),
    /**
     * A file's content key.
     */
    FILE_KEY(1u),
    /**
     * A file's metadata key.
     */
    FILE_METADATA_KEY(2u),
    /**
     * A contact's profile-tier key.
     */
    CONTACT_PROFILE_KEY(3u),
    /**
     * A contact's identifier-tier key.
     */
    CONTACT_ID_KEY(4u),
    /**
     * A hub key wrapped to a member.
     */
    HUB_KEY(5u),
    /**
     * A firehose buffer window key wrapped to the agent.
     */
    FIREHOSE_WINDOW_KEY(6u),
    /**
     * A stored message's content key (no AAD: client- and server-sealed messages
     * share a conversation with no format marker, see `crate::envelope_aad`).
     */
    MESSAGE_KEY(7u),
    /**
     * A call record's metadata content key (no AAD, same reason).
     */
    CALL_META_KEY(8u),
    /**
     * A PUK seed sealed to one device. Field: the device id.
     */
    PUK_SEED(9u),
    /**
     * A per-user audit key wrapped to an admin. Field: the audited user's pubkey.
     */
    AUDIT_USER_KEY(10u),
    /**
     * A wake-tier push payload (text).
     */
    PUSH_WAKE(11u),
    /**
     * A full-tier push payload (text).
     */
    PUSH_FULL(12u),
    /**
     * A platform role's name (text). Field: the role id.
     */
    PLATFORM_ROLE_NAME(13u),
    /**
     * A platform role's description (text). Field: the role id.
     */
    PLATFORM_ROLE_DESCRIPTION(14u),
    /**
     * A recovery share sealed to its holder's device.
     */
    RECOVERY_GROUP_SHARE(15u),
    /**
     * A recovery share contributed back to an admin. Fields: the recovery
     * session id, then the contributing device's signing pubkey.
     */
    RECOVERY_SHARE_CONTRIBUTION(16u),
    /**
     * A PUK seed sealed to a recovery group's public key.
     */
    RECOVERY_PUK_SEED(17u);

    


    companion object
}


